mapper.select:
SELECT  *  FROM t_question qu

  and deleted= 0

    and id= #{id}


    and question_type= #{questionType}


    and question_type!=7


    and  question_archive_id in

      #{id}



    and EXISTS ( select 1 from t_question_json j WHERE qu.question_frame_id = j.id
    and  j.content -> '$.title' like concat('%',#{title},'%')  limit 1 )


    and EXISTS ( select 1 from t_question_json j WHERE qu.question_frame_id = j.id
    and  j.content -> '$.vmType' like concat('%"',#{vmType},'"%')  limit 1 )


    and id not in

      #{item}



    and create_user = #{dataFilterUserId}


    and create_department_id in

      #{item}

SELECT q.id FROM t_question q

  deleted= 0

    and  question_archive_id in

      #{id}



    and difficult = #{difficult}


    and create_user = #{dataFilterUserId}


    and create_department_id in

      #{item}


  and question_type = #{questionType}
  ORDER BY RAND()  limit #{limit}

SELECT id as id , question_frame_id as  questionFrameId FROM t_question

  deleted= 0

    and  question_archive_id in

      #{id}



    and difficult = #{difficult}


    and create_user = #{dataFilterUserId}


    and create_department_id in

      #{item}


  and question_type = #{questionType}
  ORDER BY RAND()  limit #{limit}

SELECT count(*) FROM t_question q

  deleted= 0

    and  question_archive_id in

      #{id}



    and difficult = #{difficult}


    and create_user = #{dataFilterUserId}


    and create_department_id in

      #{item}


  and question_type = #{questionType}

select id
FROM t_question qu

  and deleted= 0 and question_type = #{questionType}

    and id != #{id}


    and question_archive_id = #{questionArchiveId}

  and EXISTS ( select 1 from t_question_json j WHERE qu.question_frame_id = j.id and


      REGEXP_REPLACE(j.content ->'$.title', '<span class=\\\\\"gapfilling-span\\\\\" data-gap-key=\\\\\"([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\\\\\">(.*?)</span>','') = concat('"',#{title},'"')


      j.content -> '$.title' = #{title}


  limit 1 )

limit 1
